name: Vokal AI Code Review

on:
  pull_request:
    types: [opened, synchronize, reopened]
    paths:
      - 'src/**/*.ts'
      - 'src/**/*.js'
      - 'test/**/*.ts'
      - 'test/**/*.js'
      - '*.ts'
      - '*.js'
      - '*.md'

concurrency:
  group: copilot-review-${{ github.event.pull_request.number }}
  cancel-in-progress: true

permissions:
  contents: read
  pull-requests: write
  issues: write

env:
  FORCE_COLOR: 1
  HUSKY: 0 # Disable Husky hooks in CI

jobs:
  copilot-review:
    name: AI Code Review
    runs-on: ubuntu-latest

    steps:
      - name: 📥 Checkout code
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: 📦 Setup PNPM
        uses: pnpm/action-setup@v4
        with:
          version: 9

      - name: 🔧 Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'
          cache: 'pnpm'

      - name: 📦 Install dependencies
        run: pnpm install

      - name: 🧪 Run Tests
        run: pnpm test
        continue-on-error: true

      - name: 🔍 Lint Code
        run: pnpm run lint
        continue-on-error: true

      - name: 🔍 Vokal-specific Review Summary
        uses: actions/github-script@v7
        if: github.event_name == 'pull_request' && github.event.pull_request.head.repo.full_name == github.repository
        with:
          script: |
            const { data: files } = await github.rest.pulls.listFiles({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            // Categorize changed files by Vokal feature area
            const categories = {
              'voice-testing': [],
              'tts-services': [],
              'stt-services': [],
              'audio-processing': [],
              'ai-evaluation': [],
              'cli-interface': [],
              'configuration': [],
              'documentation': [],
              'workflows': [],
              'other': []
            };

            files.forEach(file => {
              const path = file.filename;
              if (path.includes('voice-bot-test') || path.includes('voice-test') || path.includes('voice-interaction')) {
                categories['voice-testing'].push(path);
              } else if (path.includes('tts') || path.includes('text-to-speech')) {
                categories['tts-services'].push(path);
              } else if (path.includes('stt') || path.includes('speech-to-text') || path.includes('streaming-stt')) {
                categories['stt-services'].push(path);
              } else if (path.includes('audio') || path.includes('mixer') || path.includes('recording') || path.includes('assets/')) {
                categories['audio-processing'].push(path);
              } else if (path.includes('ai-comparison') || path.includes('neurolink') || path.includes('evaluation')) {
                categories['ai-evaluation'].push(path);
              } else if (path.includes('cli/') || path.includes('cli.ts')) {
                categories['cli-interface'].push(path);
              } else if (path.includes('config') || path.endsWith('.json') || path.endsWith('.yml') || path.endsWith('.yaml')) {
                categories['configuration'].push(path);
              } else if (path.endsWith('.md') || path.includes('docs/')) {
                categories['documentation'].push(path);
              } else if (path.includes('.github/workflows/')) {
                categories['workflows'].push(path);
              } else {
                categories['other'].push(path);
              }
            });

            let summary = '🤖 **Vokal AI Code Review Completed**\n\n';
            summary += '### 📋 Changed Files by Feature Area:\n\n';

            Object.entries(categories).forEach(([category, files]) => {
              if (files.length > 0) {
                const emoji = {
                  'voice-testing': '🎤',
                  'tts-services': '🗣️',
                  'stt-services': '👂',
                  'audio-processing': '🔊',
                  'ai-evaluation': '🤖',
                  'cli-interface': '⌨️',
                  'configuration': '⚙️',
                  'documentation': '📚',
                  'workflows': '🔄',
                  'other': '📄'
                }[category] || '📄';

                summary += `${emoji} **${category.replace('-', ' ').toUpperCase()}** (${files.length} files)\n`;
                files.forEach(file => summary += `   - \`${file}\`\n`);
                summary += '\n';
              }
            });

            summary += '### 🔍 Review Focus Areas:\n';
            summary += '- **Voice Testing**: Test execution, scenario handling, result validation\n';
            summary += '- **TTS/STT Services**: Provider integration, API calls, error handling\n';
            summary += '- **Audio Processing**: Mixing, recording, playback, format conversion\n';
            summary += '- **AI Evaluation**: Response analysis, comparison accuracy, prompt engineering\n';
            summary += '- **Security**: API key handling, file system safety, input validation\n';
            summary += '- **Performance**: Memory usage, streaming efficiency, async operations\n';
            summary += '- **Cross-Platform**: macOS/Linux compatibility, audio device handling\n\n';
            summary += '📝 Check the **Files Changed** tab for detailed review of each file.\n';
            summary += '🚀 Ensure all Vokal features (TTS, STT, Audio Mixing, AI Evaluation) work seamlessly together!';

            github.rest.issues.createComment({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: summary
            });

# Testing Guide

This guide covers testing strategies and best practices for Vokal.

## Test Structure

```
test/
├── unit/              # Unit tests
├── integration/       # Integration tests
├── e2e/              # End-to-end tests
├── fixtures/         # Test data and fixtures
└── helpers/          # Test utilities
```

## Running Tests

### All Tests

```bash
npm test
```

### Specific Test Suites

```bash
# Unit tests only
npm run test:unit

# Integration tests
npm run test:integration

# E2E tests
npm run test:e2e
```

### Watch Mode

```bash
npm run test:watch
```

### Coverage

```bash
npm run test:coverage
```

## Writing Tests

### Unit Tests

Test individual functions and classes in isolation.

**Example: Testing Audio Mixer**

```typescript
import { mixAudio } from '../src/services/audio-mixer';
import { readFileSync } from 'fs';

describe('AudioMixer', () => {
  let testAudio: Buffer;

  beforeEach(() => {
    testAudio = readFileSync('test/fixtures/test-audio.wav');
  });

  it('should mix audio with background noise', async () => {
    const result = await mixAudio({
      sourceAudio: testAudio,
      backgroundNoise: 'cafe-ambience.wav',
      noiseLevel: 0.3
    });

    expect(result).toBeInstanceOf(Buffer);
    expect(result.length).toBeGreaterThan(0);
  });

  it('should throw error for invalid noise level', async () => {
    await expect(mixAudio({
      sourceAudio: testAudio,
      backgroundNoise: 'cafe-ambience.wav',
      noiseLevel: 1.5
    })).rejects.toThrow('Noise level must be between 0 and 1');
  });

  it('should handle missing background noise file', async () => {
    await expect(mixAudio({
      sourceAudio: testAudio,
      backgroundNoise: 'nonexistent.wav',
      noiseLevel: 0.3
    })).rejects.toThrow('Background noise file not found');
  });
});
```

### Integration Tests

Test interactions between multiple components.

**Example: Testing STT Handler Manager**

```typescript
import { STTHandlerManager } from '../src/providers/stt-handler-manager';
import { registerSTTHandler } from '../src/providers/stt-registry';

describe('STTHandlerManager Integration', () => {
  beforeEach(() => {
    // Register mock handler
    registerSTTHandler('mock-stt', {
      async transcribe(audio: Buffer) {
        return 'mock transcription';
      },
      supports: {
        streaming: false,
        languageCodes: ['en-US'],
        encoding: ['LINEAR16']
      }
    });
  });

  it('should transcribe audio using registered handler', async () => {
    const manager = new STTHandlerManager('mock-stt');
    const audio = Buffer.from('test audio data');

    const result = await manager.transcribe(audio);

    expect(result).toBe('mock transcription');
  });

  it('should throw error for unregistered handler', () => {
    expect(() => {
      new STTHandlerManager('nonexistent-handler');
    }).toThrow('STT handler not found');
  });
});
```

### End-to-End Tests

Test complete workflows from CLI to results.

**Example: Testing Voice Bot Test**

```typescript
import { runVoiceTest } from '../src/services/voice-test';
import { readFileSync } from 'fs';

describe('Voice Bot Test E2E', () => {
  it('should run complete voice bot test', async () => {
    const config = {
      sttProvider: 'google-ai',
      scenarios: [
        {
          prompt: 'Hello, how can I help you?',
          expectedResponse: 'I need assistance with my order'
        }
      ],
      audioSettings: {
        sampleRate: 16000,
        channels: 1,
        encoding: 'LINEAR16'
      }
    };

    const result = await runVoiceTest(config);

    expect(result.summary.total).toBe(1);
    expect(result.scenarios[0].transcription).toBeDefined();
    expect(result.scenarios[0].evaluation).toBeDefined();
  }, 30000); // 30 second timeout for E2E test
});
```

## Mocking

### Mocking STT Providers

```typescript
import { jest } from '@jest/globals';

const mockSTTHandler = {
  transcribe: jest.fn().mockResolvedValue('mocked transcription'),
  supports: {
    streaming: true,
    languageCodes: ['en-US'],
    encoding: ['LINEAR16']
  }
};
```

### Mocking Audio Recording

```typescript
import { jest } from '@jest/globals';

jest.mock('../src/services/audio-recording', () => ({
  startRecording: jest.fn().mockReturnValue({
    stop: jest.fn().mockResolvedValue(Buffer.from('mock audio'))
  })
}));
```

### Mocking AI Comparison

```typescript
import { jest } from '@jest/globals';

jest.mock('../src/services/ai-comparison', () => ({
  compareResponses: jest.fn().mockResolvedValue({
    score: 0.95,
    passed: true,
    details: {
      semanticSimilarity: 0.95,
      reasoning: 'Responses are very similar'
